83	    function convertTableToMarkdown(table) {
84	        const rows = [];
85	        const headerRow = table.querySelector('thead tr');
86	        const bodyRows = table.querySelectorAll('tbody tr');
87	
88	        // Process header row
89	        if (headerRow) {
90	            const headers = [];
91	            headerRow.querySelectorAll('th').forEach(th => {
92	                headers.push(convertElementToMarkdown(th).replace(/\n/g, ' ').trim());
93	            });
94	            if (headers.length > 0) {
95	                rows.push('| ' + headers.join(' | ') + ' |');
96	                rows.push('| ' + headers.map(() => '---').join(' | ') + ' |');
97	            }
98	        }
99	
100	        // Process body rows
101	        bodyRows.forEach(tr => {
102	            const cells = [];
103	            tr.querySelectorAll('td, th').forEach(cell => {
104	                cells.push(convertElementToMarkdown(cell).replace(/\n/g, ' ').trim());
105	            });
106	            if (cells.length > 0) {
107	                rows.push('| ' + cells.join(' | ') + ' |');
108	            }
109	        });
110	
111	        return rows.length > 0 ? '\n\n' + rows.join('\n') + '\n\n' : '';
112	    }
