400	    function findMessages() {
401	        // More specific selectors to avoid nested elements
402	        const selectors = [
403	            'div[data-message-author-role]', // Modern ChatGPT with clear author role
404	            'article[data-testid*="conversation-turn"]', // Conversation turns
405	            'div[data-testid="conversation-turn"]', // Specific conversation turn
406	            '.group\\/conversation-turn', // Fix for issue #6: More specific selector for conversation turns
407	            'div[class*="group"]:not([class*="group"] [class*="group"])', // Top-level groups only
408	        ];
409	
410	        let messages = [];
411	        for (const selector of selectors) {
412	            messages = document.querySelectorAll(selector);
413	            if (messages.length > 0) {
414	                console.log(`Using selector: ${selector}, found ${messages.length} messages`);
415	                break;
416	            }
417	        }
418	
419	        if (messages.length === 0) {
420	            // Fallback: try to find conversation container and parse its structure
421	            const conversationContainer = document.querySelector('[role="main"], main, .conversation, [class*="conversation"]');
422	            if (conversationContainer) {
423	                // Look for direct children that seem like message containers
424	                messages = conversationContainer.querySelectorAll(':scope > div, :scope > article');
425	                console.log(`Fallback: found ${messages.length} potential messages in conversation container`);
426	            }
427	        }
428	
429	        // Filter and validate messages
430	        const validMessages = Array.from(messages).filter(msg => {
431	            const text = msg.textContent.trim();
432	
433	            // Must have some content (reduced threshold for Chinese text)
434	            if (text.length < 5) return false;
435	            if (text.length > 100000) return false;
436	
437	            // Skip elements that are clearly UI components
438	            if (msg.querySelector('input[type="text"], textarea')) return false;
439	            if (msg.classList.contains('typing') || msg.classList.contains('loading')) return false;
440	
441	            return true;
442	        });
443	
444	        // Remove nested messages and consolidate content
445	        const consolidatedMessages = [];
446	        const usedElements = new Set();
447	
448	        validMessages.forEach(msg => {
449	            if (usedElements.has(msg)) return;
450	            
451	            // Check if this message is nested within another valid message
452	            const isNested = validMessages.some(other => 
453	                other !== msg && other.contains(msg) && !usedElements.has(other)
454	            );
455	            
456	            if (!isNested) {
457	                consolidatedMessages.push(msg);
458	                usedElements.add(msg);
459	            }
460	        });
461	
462	        return consolidatedMessages;
463	    }
