465	    function findReplyLabel(messageElement) {
466	        // Look for reply labels like "回复 1", "回复 2" in sibling or parent elements
467	        const parent = messageElement.closest('.flex.max-w-full');
468	        if (parent && parent.previousElementSibling) {
469	            const labelEl = parent.previousElementSibling.querySelector('.font-semibold, [class*="font-semibold"]');
470	            if (labelEl) {
471	                const text = labelEl.textContent.trim();
472	                if (/^回复\s*\d+$/.test(text) || /^Response\s*\d+$/i.test(text)) {
473	                    return text;
474	                }
475	            }
