562	    function extractConversationTitle() {
563	        // Try to get actual conversation title
564	        const titleSelectors = [
565	            'h1:not([class*="hidden"])',
566	            '[class*="conversation-title"]',
567	            '[data-testid*="conversation-title"]',
568	            'title'
569	        ];
570	
571	        for (const selector of titleSelectors) {
572	            const element = document.querySelector(selector);
573	            if (element && element.textContent.trim()) {
574	                const title = element.textContent.trim();
575	                // Avoid generic titles
576	                if (!['chatgpt', 'new chat', 'untitled', 'chat'].includes(title.toLowerCase())) {
577	                    return title;
578	                }
579	            }
580	        }
581	
582	        return 'Conversation with ChatGPT';
583	    }
