491	    function identifySender(messageElement, index, allMessages) {
492	        // Method 1: Check for data attributes (most reliable)
493	        const authorRole = messageElement.getAttribute('data-message-author-role');
494	        if (authorRole) {
495	            return { sender: authorRole === 'user' ? 'You' : 'ChatGPT', reliable: true };
496	        }
497	
498	        // Method 2: Look for avatar images with better detection
499	        const avatars = messageElement.querySelectorAll('img');
500	        for (const avatar of avatars) {
501	            const alt = avatar.alt?.toLowerCase() || '';
502	            const src = avatar.src?.toLowerCase() || '';
503	            const classes = avatar.className?.toLowerCase() || '';
504	
505	            // User indicators
506	            if (alt.includes('user') || src.includes('user') || classes.includes('user')) {
507	                return { sender: 'You', reliable: false };
508	            }
509	
510	            // Assistant indicators
511	            if (alt.includes('chatgpt') || alt.includes('assistant') || alt.includes('gpt') ||
512	                src.includes('assistant') || src.includes('chatgpt') || classes.includes('assistant')) {
513	                return { sender: 'ChatGPT', reliable: false };
514	            }
515	        }
516	
517	        // Method 3: Content analysis with better patterns
518	        const text = messageElement.textContent.toLowerCase();
519	        const textStart = text.substring(0, 200); // Look at beginning of message
520	
521	        // Strong ChatGPT indicators
522	        if (textStart.match(/^(i understand|i can help|here's|i'll|let me|i'd be happy|certainly|of course)/)) {
523	            return { sender: 'ChatGPT', reliable: false };
524	        }
525	
526	        // Strong user indicators
527	        if (textStart.match(/^(can you|please help|how do i|i need|i want|help me|could you)/)) {
528	            return { sender: 'You', reliable: false };
529	        }
530	
531	        // Method 4: Structural analysis - look at DOM structure
532	        const hasCodeBlocks = messageElement.querySelectorAll('pre, code').length > 0;
533	        const hasLongText = messageElement.textContent.length > 200;
534	        const hasLists = messageElement.querySelectorAll('ul, ol, li').length > 0;
535	
536	        // ChatGPT messages tend to be longer and more structured
537	        if (hasCodeBlocks && hasLongText && hasLists) {
538	            return { sender: 'ChatGPT', reliable: false };
539	        }
540	
541	        // Method 5: Position-based fallback with better logic
542	        // Try to detect actual alternating pattern by looking at content characteristics
543	        if (index > 0 && allMessages[index - 1]) {
544	            const prevText = allMessages[index - 1].textContent;
545	            const currentText = messageElement.textContent;
546	
547	            // If previous was short and current is long, likely user -> assistant
548	            if (prevText.length < 100 && currentText.length > 300) {
549	                return { sender: 'ChatGPT', reliable: false };
550	            }
551	
552	            // If previous was long and current is short, likely assistant -> user
553	            if (prevText.length > 300 && currentText.length < 100) {
554	                return { sender: 'You', reliable: false };
555	            }
556	        }
557	
558	        // Final fallback
559	        return { sender: index % 2 === 0 ? 'You' : 'ChatGPT', reliable: false };
560	    }
561	
562	    function extractConversationTitle() {
563	        // Try to get actual conversation title
564	        const titleSelectors = [
565	            'h1:not([class*="hidden"])',
566	            '[class*="conversation-title"]',
567	            '[data-testid*="conversation-title"]',
568	            'title'
569	        ];
570	
571	        for (const selector of titleSelectors) {
572	            const element = document.querySelector(selector);
573	            if (element && element.textContent.trim()) {
574	                const title = element.textContent.trim();
575	                // Avoid generic titles
576	                if (!['chatgpt', 'new chat', 'untitled', 'chat'].includes(title.toLowerCase())) {
577	                    return title;
578	                }
579	            }
580	        }
581	
582	        return 'Conversation with ChatGPT';
583	    }
584	
585	    // Main export logic
586	    const messages = findMessages();
587	    
588	    if (messages.length === 0) {
589	        alert('No messages found. The page structure may have changed.');
590	        return;
591	    }
592	
593	    console.log(`Processing ${messages.length} messages...`);
594	
595	    const lines = [];
596	    const title = extractConversationTitle();
597	    const date = formatDate();
598	    const url = window.location.href;
599	
600	    lines.push(`# ${title}\n`);
601	    lines.push(`**Date:** ${date}`);
602	    lines.push(`**Source:** [chat.openai.com](${url})\n`);
603	    lines.push(`---\n`);
604	
605	    // Process messages with better duplicate detection
606	    const processedMessages = [];
607	    const seenContent = new Set();
608	
609	    console.log('Converting images to base64...');
610	    for (let index = 0; index < messages.length; index++) {
611	        const messageElement = messages[index];
612	        const { sender, reliable } = identifySender(messageElement, index, messages);
613	        const replyLabel = findReplyLabel(messageElement);
614	        const content = await processMessageContent(messageElement);
615	
616	        // Skip if empty or too short (reduced threshold for Chinese text)
617	        if (!content || content.trim().length < 5) {
618	            console.log(`Skipping message ${index}: too short or empty`);
619	            continue;
620	        }
621	
622	        // Create a content hash for duplicate detection
623	        const contentHash = content.substring(0, 100).replace(/\s+/g, ' ').trim();
624	        if (seenContent.has(contentHash)) {
625	            console.log(`Skipping message ${index}: duplicate content`);
626	            continue;
627	        }
628	        seenContent.add(contentHash);
629	
630	        processedMessages.push({
631	            sender,
632	            reliable,
633	            replyLabel,
634	            content,
635	            originalIndex: index
636	        });
637	
638	        console.log(`Processed message ${index + 1}/${messages.length}`);
639	    }
640	
641	    // Apply sender sequence correction only for unreliable detections
642	    for (let i = 1; i < processedMessages.length; i++) {
643	        const current = processedMessages[i];
644	        const previous = processedMessages[i - 1];
645	
646	        // Skip correction if either sender was reliably detected
647	        if (current.reliable || previous.reliable) {
648	            continue;
649	        }
650	
651	        // If we have two consecutive messages from the same sender, try to fix it
652	        if (current.sender === previous.sender) {
653	            // Use content analysis to determine which should be flipped
654	            const currentLength = current.content.length;
655	            const previousLength = previous.content.length;
656	
657	            // If current message is much longer, it's likely ChatGPT
658	            if (currentLength > previousLength * 2 && currentLength > 500) {
659	                current.sender = 'ChatGPT';
660	            } else if (previousLength > currentLength * 2 && previousLength > 500) {
661	                previous.sender = 'ChatGPT';
662	                current.sender = 'You';
663	            } else {
664	                // Default alternating fix
665	                current.sender = current.sender === 'You' ? 'ChatGPT' : 'You';
666	            }
667	
668	            console.log(`Fixed consecutive ${previous.sender} messages at positions ${i-1} and ${i}`);
669	        }
670	    }
671	
672	    // Generate final output
673	    processedMessages.forEach(({ sender, replyLabel, content }) => {
674	        const label = replyLabel ? ` (${replyLabel})` : '';
675	        lines.push(`### **${sender}**${label}\n`);
676	        lines.push(content);
677	        lines.push('\n---\n');
678	    });
679	
680	    // Create and download file
681	    const markdownContent = lines.join('\n');
682	    const blob = new Blob([markdownContent], { type: 'text/markdown' });
683	    const url2 = URL.createObjectURL(blob);
684	    const a = document.createElement('a');
685	    a.href = url2;
686	    // Use document title for better file naming (Issue #12)
687	    const safeTitle = document.title.replace(/[<>:"/\\|?*]/g, '').replace(/\s+/g, ' ').trim();
688	    a.download = safeTitle ? `${safeTitle} (${date}).md` : `ChatGPT_Conversation_${date}.md`;
689	    document.body.appendChild(a);
690	    a.click();
691	    document.body.removeChild(a);
692	    URL.revokeObjectURL(url2);
693	
694	    console.log(`Export completed: ${processedMessages.length} messages exported`);
695	})();
